declare(strict_types=1);

namespace Manipulus\Bundles\Test\Unit\Plugin;

use Magento\Framework\App\Filesystem\DirectoryList;
use Magento\Framework\Filesystem;
use Magento\Framework\Filesystem\Directory\Read;
use Magento\Framework\Filesystem\Driver\File as FileDriver;
use Magento\Framework\Filesystem\DriverPool;
use Magento\Framework\Filesystem\File\ReadFactory;
use Magento\Framework\RequireJs\Config\File\Collector\Aggregated;
use Magento\Framework\Serialize\Serializer\Json;
use Magento\Framework\View\Asset\ContextInterface;
use Magento\Framework\View\Asset\Minification;
use Magento\Framework\View\Asset\Repository;
use Magento\Framework\View\Design\ThemeInterface;
use Magento\Framework\View\File;
use Manipulus\Bundles\Model\CommandLine;
use Manipulus\Bundles\Model\DeployedBundles;
use Manipulus\Bundles\Plugin\WithholdUndeployedBundlesPlugin;
use PHPUnit\Framework\TestCase;

/**
 * The bundles map against real bundle files in a temporary static directory.
 */
class WithholdUndeployedBundlesPluginTest extends TestCase
{
    private const STATIC_PATH = 'frontend/Magento/luma/en_US';

    private const CONFIG = <<<'JS'
// Generated by manipulus.
var config = {
    "bundles": {
        "manipulus/bundle-common": ["jquery"],
        "manipulus/bundle-product": ["Magento_Catalog/js/price-box"]
    }
};

JS;

    private FileDriver $driver;

    private string $root;

    protected function setUp(): void
    {
        $this->driver = new FileDriver();
        $this->root = sys_get_temp_dir() . '/manipulus-test-' . bin2hex(random_bytes(6));
        $this->driver->createDirectory($this->root . '/module/view/frontend');
        $this->driver->createDirectory($this->root . '/static/' . self::STATIC_PATH);
        $this->driver->filePutContents($this->moduleConfig(), self::CONFIG);
    }

    protected function tearDown(): void
    {
        $this->driver->deleteDirectory($this->root);
    }

    public function testTheMapIsContributedWhenEveryBundleItNamesIsDeployed(): void
    {
        $this->deploy('common', 'product');
        [$catalog, $bundles] = $this->files();

        $this->assertSame([$catalog, $bundles], $this->merge($this->plugin(), [$catalog, $bundles]));
    }

    public function testTheMapIsWithheldWhenItsBundlesAreNotDeployed(): void
    {
        [$catalog, $bundles] = $this->files();

        $this->assertSame([$catalog], $this->merge($this->plugin(), [$catalog, $bundles]));
    }

    public function testOneMissingBundleWithholdsTheWholeMap(): void
    {
        $this->deploy('common');
        [$catalog, $bundles] = $this->files();

        $this->assertSame([$catalog], $this->merge($this->plugin(), [$catalog, $bundles]));
    }

    public function testAStaticDeployKeepsTheMapBecauseTheBundlesAreWrittenAfterIt(): void
    {
        [$catalog, $bundles] = $this->files();

        $this->assertSame([$catalog, $bundles], $this->merge($this->plugin(true), [$catalog, $bundles]));
    }

    public function testFilesOtherThanTheRequireJsConfigAreLeftAlone(): void
    {
        [$catalog, $bundles] = $this->files();

        $merged = $this->merge($this->plugin(), [$catalog, $bundles], 'requirejs-map.js');

        $this->assertSame([$catalog, $bundles], $merged);
    }

    private function moduleConfig(): string
    {
        return $this->root . '/module/view/frontend/requirejs-config.js';
    }

    private function deploy(string ...$names): void
    {
        $directory = $this->root . '/static/' . self::STATIC_PATH . '/' . DeployedBundles::DIRECTORY;
        $this->driver->createDirectory($directory);
        foreach ($names as $name) {
            $this->driver->filePutContents("{$directory}/bundle-{$name}.js", 'define("x", [], function () {});');
        }
    }

    /**
     * @return File[] another module's config, then this module's
     */
    private function files(): array
    {
        return [
            new File($this->root . '/Magento_Catalog/view/frontend/requirejs-config.js', 'Magento_Catalog'),
            new File($this->moduleConfig(), 'Manipulus_Bundles'),
        ];
    }

    /**
     * @param File[] $files
     * @return File[]
     */
    private function merge(
        WithholdUndeployedBundlesPlugin $plugin,
        array $files,
        string $filePath = 'requirejs-config.js'
    ): array {
        return $plugin->afterGetFiles(
            $this->createMock(Aggregated::class),
            $files,
            $this->createMock(ThemeInterface::class),
            $filePath
        );
    }

    private function plugin(bool $onTheCommandLine = false): WithholdUndeployedBundlesPlugin
    {
        $static = new Read(new ReadFactory(new DriverPool()), $this->driver, $this->root . '/static');
        $filesystem = $this->createMock(Filesystem::class);
        $filesystem->method('getDirectoryRead')->with(DirectoryList::STATIC_VIEW)->willReturn($static);

        $minification = $this->createMock(Minification::class);
        $minification->method('addMinifiedSign')->willReturnArgument(0);

        $context = $this->createMock(ContextInterface::class);
        $context->method('getPath')->willReturn(self::STATIC_PATH);
        $assetRepository = $this->createMock(Repository::class);
        $assetRepository->method('getStaticViewFileContext')->willReturn($context);

        $commandLine = $this->createMock(CommandLine::class);
        $commandLine->method('isCurrent')->willReturn($onTheCommandLine);

        return new WithholdUndeployedBundlesPlugin(
            new DeployedBundles($filesystem, $this->driver, new Json(), $minification),
            $assetRepository,
            $commandLine
        );
    }
}
